import{_ as e}from"./chunks/100.I7A0VXqr.js";import{_ as a,o,c as i,ak as r}from"./chunks/framework.DC-k2h36.js";const n="/projects/esp32Sensor/en/latest/assets/1.3H1LOnBh.webp",l="/projects/esp32Sensor/en/latest/assets/2.JIxdOrkS.webp",s="/projects/esp32Sensor/en/latest/assets/3.BfM4hT-O.webp",d="/projects/esp32Sensor/en/latest/assets/4.MDYTEaIg.webp",b=JSON.parse('{"title":"15. Dot Matrix Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/15. Dot Matrix Module.md","filePath":"docs/15. Dot Matrix Module.md"}'),c={name:"docs/15. Dot Matrix Module.md"};function h(p,t,m,u,g,x){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_15-dot-matrix-module" tabindex="-1">15. Dot Matrix Module <a class="header-anchor" href="#_15-dot-matrix-module" aria-label="Permalink to &quot;15. Dot Matrix Module&quot;">​</a></h1><h2 id="_15-1-introduction" tabindex="-1">15.1 Introduction <a class="header-anchor" href="#_15-1-introduction" aria-label="Permalink to &quot;15.1 Introduction&quot;">​</a></h2><p>The dot matrix module is an LED display module characterized by high brightness, flicker-free operation, and convenient wiring. It displays numbers, text strings, custom patterns, and graphical icons.</p><img loading="lazy" height="1387" width="1387" src="'+n+'" class="common_img" style="width:300px;"><h2 id="_15-2-technical-specifications" tabindex="-1">15.2 Technical Specifications <a class="header-anchor" href="#_15-2-technical-specifications" aria-label="Permalink to &quot;15.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Operating current</td><td style="text-align:center;">45 mA</td></tr><tr><td style="text-align:center;">Resolution</td><td style="text-align:center;">8 × 16 pixels</td></tr><tr><td style="text-align:center;">Brightness levels</td><td style="text-align:center;">8 adjustable levels</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">55.4 × 23.4 × 18.4 mm</td></tr></tbody></table><h2 id="_15-3-hands-on-project" tabindex="-1">15.3 Hands-On Project <a class="header-anchor" href="#_15-3-hands-on-project" aria-label="Permalink to &quot;15.3 Hands-On Project&quot;">​</a></h2><h3 id="_15-3-1-project-overview" tabindex="-1">15.3.1 Project Overview <a class="header-anchor" href="#_15-3-1-project-overview" aria-label="Permalink to &quot;15.3.1 Project Overview&quot;">​</a></h3><p>This project uses the dot matrix module to cycle through static text, numbers, a heart pattern, and scrolling text, pausing for 3 s on each item. It demonstrates how to initialize the module, adjust screen brightness, and switch between different types of display content.</p><h3 id="_15-3-2-hardware-wiring" tabindex="-1">15.3.2 Hardware Wiring <a class="header-anchor" href="#_15-3-2-hardware-wiring" aria-label="Permalink to &quot;15.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the dot matrix module to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="870" src="'+l+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_15-3-3-adding-extensions" tabindex="-1">15.3.3 Adding Extensions <a class="header-anchor" href="#_15-3-3-adding-extensions" aria-label="Permalink to &quot;15.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Dot matrix module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;"><h3 id="_15-3-4-complete-program-and-analysis" tabindex="-1">15.3.4 Complete Program and Analysis <a class="header-anchor" href="#_15-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;15.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>On startup, the dot matrix module is initialized on port P5, and its brightness is set to 5.</p></li><li><p>Inside the main program loop, the display routine cycles through each item in sequence:</p><ul><li><p>Display text &quot;Hi&quot; at coordinates (0, 0) and wait 3 s.</p></li><li><p>Display number 123 and wait 3 s.</p></li><li><p>Display a heart pattern and wait 3 s.</p></li><li><p>Scroll text &quot;Hello&quot; at coordinates (0, 0) and wait 3 s.</p></li></ul></li><li><p>The display cycle repeats continuously.</p></li></ol><img loading="lazy" height="781" width="637" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/15 Dot Matrix Module.sb3</a>.</strong></p></div><h3 id="_15-3-5-program-upload" tabindex="-1">15.3.5 Program Upload <a class="header-anchor" href="#_15-3-5-program-upload" aria-label="Permalink to &quot;15.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_15-3-6-implementation-outcome" tabindex="-1">15.3.6 Implementation Outcome <a class="header-anchor" href="#_15-3-6-implementation-outcome" aria-label="Permalink to &quot;15.3.6 Implementation Outcome&quot;">​</a></h3><p>Once the program upload is complete, the dot matrix module cycles through content in sequence: displaying the text &quot;Hi&quot;, showing the number 123, drawing a heart pattern, and finally scrolling the text &quot;Hello&quot;. Each item stays visible for 3 s before switching automatically in a continuous loop.</p>',25)])])}const f=a(c,[["render",h]]);export{b as __pageData,f as default};
